import {rejectionError} from './rejectionError.js';

// spec: specs/hal-engine-config-hooks/spec.md#8
it('preserves Error identity and wraps other rejections with their original cause', () => {
  const original = new Error('original');
  expect(rejectionError(original)).toBe(original);
  for (const value of ['string boom', {code: 503}, undefined]) {
    const error = rejectionError(value);
    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe(String(value));
    expect(Object.hasOwn(error, 'cause')).toBe(true);
    expect(error.cause).toBe(value);
  }
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/rejectionError.test.ts --runInBand"
